<PageTitle>Track Shipment</PageTitle>

<div class="container">
    <h1 class="mb-4">Track Your Shipment</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001-2024)"
                       @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (searched && shipment is null && !isLoading)
    {
        <div class="alert alert-warning">
            No shipment found with tracking number "<strong>@searchedNumber</strong>".
        </div>
    }

    @if (shipment is not null)
    {
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
