+@page "/track"
+@using ShipmentTracker.Client.Models
+@using ShipmentTracker.Client.Services
+@inject IShipmentService ShipmentService
+
+<PageTitle>Track Shipment</PageTitle>
+
+<div class="container">
+    <h1 class="mb-4">Track Your Shipment</h1>
+
+    <div class="row mb-4">
+        <div class="col-md-6">
+            <div class="input-group">
+                <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001-2024)"
+                       @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
+                <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
+                    @if (isLoading)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+                    }
+                    Track
+                </button>
+            </div>
+        </div>
+    </div>
+
+    @if (searched && shipment is null && !isLoading)
+    {
+        <div class="alert alert-warning">
+            No shipment found with tracking number "<strong>@searchedNumber</strong>".
+        </div>
+    }
+
+    @if (shipment is not null)
+    {
+        <div class="card">
+            <div class="card-header d-flex justify-content-between align-items-center">
+                <strong>@shipment.TrackingNumber</strong>
+                <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
+            </div>
+            <div class="card-body">
+                <div class="row">
+                    <div class="col-md-6">
+                        <p><strong>Description:</strong> @shipment.Description</p>
+                        <p><strong>Origin:</strong> @shipment.Origin</p>
+                        <p><strong>Destination:</strong> @shipment.Destination</p>
+                    </div>
+                    <div class="col-md-6">
+                        <p><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
+                        <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
+                        @if (shipment.ActualDelivery.HasValue)
+                        {
+                            <p><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
+                        }
+                    </div>
+                </div>
+            </div>
+        </div>
+    }
+</div>
+
+@code {
+    private string trackingNumber = string.Empty;
+    private string searchedNumber = string.Empty;
+    private Shipment? shipment;
+    private bool isLoading;
+    private bool searched;
+
+    private async Task HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+            await SearchShipment();
+    }
+
+    private async Task SearchShipment()
+    {
+        if (string.IsNullOrWhiteSpace(trackingNumber))
+            return;
+
+        isLoading = true;
+        searched = true;
+        searchedNumber = trackingNumber.Trim();
+        shipment = null;
+
+        try
+        {
+            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
+        }
+        catch
+        {
+            shipment = null;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Exception => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
