+    <h1 class="mb-4">Dispatch Dashboard</h1>
+
+    <div class="row mb-3">
+        <div class="col-md-3">
+            <select class="form-select" @bind="statusFilter">
+                <option value="">All Statuses</option>
+                @foreach (var status in Enum.GetValues<ShipmentStatus>())
+                {
+                    <option value="@status">@status</option>
+                }
+            </select>
+        </div>
+        <div class="col-md-3">
+            <input type="text" class="form-control" placeholder="Search shipments..."
+                   @bind="searchTerm" @bind:event="oninput" />
+        </div>
+        <div class="col-md-3">
+            <button class="btn btn-outline-secondary" @onclick="RefreshData" disabled="@isLoading">
+                <span class="bi bi-arrow-clockwise"></span> Refresh
+            </button>
+        </div>
+    </div>
+
+    @if (isLoading)
+    {
+        <div class="d-flex justify-content-center my-5">
+            <div class="spinner-border text-primary" role="status">
+                <span class="visually-hidden">Loading...</span>
+            </div>
+        </div>
+    }
+    else if (errorMessage is not null)
+    {
+        <div class="alert alert-danger">@errorMessage</div>
+    }
+    else
+    {
+        <div class="table-responsive">
+            <table class="table table-striped table-hover">
+                <thead class="table-dark">
+                    <tr>
+                        <th>Tracking #</th>
+                        <th>Origin</th>
+                        <th>Destination</th>
+                        <th>Customer</th>
+                        <th>Status</th>
+                        <th>Est. Delivery</th>
+                        <th>Actions</th>
+                    </tr>
+                </thead>
+                <tbody>
+                    @foreach (var s in filteredShipments)
+                    {
+                        <tr>
+                            <td><strong>@s.TrackingNumber</strong></td>
+                            <td>@s.Origin</td>
+                            <td>@s.Destination</td>
+                            <td>@s.CustomerEmail</td>
+                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
+                            <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
+                            <td>
+                                @if (s.Status != ShipmentStatus.Delivered)
+                                {
+                                    <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
+                                            value="@s.Status" @onchange="(e) => UpdateStatus(s, e)">
+                                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
+                                        {
+                                            <option value="@status" selected="@(s.Status == status)">@status</option>
+                                        }
+                                    </select>
+                                }
+                                else
+                                {
+                                    <span class="text-muted">Completed</span>
+                                }
+                            </td>
+                        </tr>
+                    }
+                </tbody>
+            </table>
+        </div>
+
+        <div class="mt-3 text-muted">
+            Showing @filteredShipments.Count() of @shipments.Count shipments
+        </div>
+    }
+</div>
+
+@code {
+    private List<Shipment> shipments = [];
+    private bool isLoading = true;
+    private string? errorMessage;
+    private string statusFilter = string.Empty;
+    private string searchTerm = string.Empty;
+
+    private IEnumerable<Shipment> filteredShipments => shipments
+        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
+        .Where(s => string.IsNullOrEmpty(searchTerm) ||
+                    s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
+                    s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
+                    s.Origin.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
+                    s.CustomerEmail.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
+
+    protected override async Task OnInitializedAsync()
+    {
+        await RefreshData();
+    }
+
+    private async Task RefreshData()
+    {
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            shipments = await ShipmentService.GetAllShipmentsAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load shipments: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
+    {
+        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
+        {
+            try
+            {
+                var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
+                shipment.Status = updated.Status;
+                shipment.ActualDelivery = updated.ActualDelivery;
+            }
+            catch (Exception ex)
+            {
+                errorMessage = $"Failed to update status: {ex.Message}";
+            }
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Exception => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
